import torch
from phase1_self_reference_model import SelfReferenceNet
torch.set_num_threads(2);torch.backends.mkldnn.enabled=True;torch.manual_seed(71);m=SelfReferenceNet();x=torch.randn(8,2,256);target=torch.randn_like(x);y=m(x);assert torch.allclose(x,y,atol=3e-6,rtol=3e-6);params=list(m.parameters());loss=(y-target).square().mean();z=torch.autograd.grad(loss*0,params,retain_graph=True,allow_unused=True);a=torch.autograd.grad(loss,params,retain_graph=True,allow_unused=True);b=torch.autograd.grad(2*loss,params,allow_unused=True);assert all(g is None or torch.count_nonzero(g)==0 for g in z);assert all(g is None or torch.isfinite(g).all() for g in a);assert all(g is None or h is None or torch.allclose(h,2*g,atol=2e-6,rtol=2e-5) for g,h in zip(a,b));assert a[-2].abs().sum()>0
z=torch.randn(4,256,dtype=torch.complex64);angle=torch.polar(torch.ones(4),torch.tensor([-.8,-.3,.4,1.2]));z[:,80:144]=z[:,:64]*angle[:,None];ref,corr=SelfReferenceNet.reference(z);assert torch.allclose(ref[:,:144],z[:,:144],atol=2e-6,rtol=2e-6);assert torch.allclose(corr,torch.ones_like(corr),atol=2e-6);print('PASS identity, gradient linearity, finite training gradient, exact phase-aligned self reference')
